r, c, k = map(int, input().split())
g = tuple(input().strip() for _ in range(r))
def step(g):
    res = []
    for i in range(r):
        row = []
        for j in range(c):
            n = 0
            for di in (-1, 0, 1):
                for dj in (-1, 0, 1):
                    if di or dj:
                        n += g[(i + di) % r][(j + dj) % c] == "1"
            row.append("1" if n == 3 or (n == 2 and g[i][j] == "1") else "0")
        res.append("".join(row))
    return tuple(res)
seen = {g: 0}
hist = [g]
t = 0
while t < k:
    g = step(g)
    t += 1
    if g in seen:
        start = seen[g]
        period = t - start
        g = hist[start + (k - start) % period]
        break
    seen[g] = t
    hist.append(g)
print("\n".join(g))

